{"path": "wordy.py", "content": "OPERATIONS = {
    "plus": lambda x, y: x + y,
    "minus": lambda x, y: x - y,
    "multiplied": lambda x, y: x * y,
    "divided": lambda x, y: int(x / y),
}


def _is_number(token):
    try:
        int(token)
    except ValueError:
        return False
    return True


def answer(question):
    prefix = "What is"
    if not question.startswith(prefix):
        raise ValueError("unknown operation")

    body = question[len(prefix):].strip().rstrip("?").strip()
    body = body.replace("multiplied by", "multiplied").replace("divided by", "divided")
    tokens = body.split()

    for token in tokens:
        if not _is_number(token) and token not in OPERATIONS:
            raise ValueError("unknown operation")

    if not tokens or not _is_number(tokens[0]):
        raise ValueError("syntax error")

    result = int(tokens[0])
    index = 1
    while index < len(tokens):
        operation = tokens[index]
        if operation not in OPERATIONS:
            raise ValueError("syntax error")
        if index + 1 >= len(tokens) or not _is_number(tokens[index + 1]):
            raise ValueError("syntax error")
        if operation == "divided" and int(tokens[index + 1]) == 0:
            raise ValueError("syntax error")
        result = OPERATIONS[operation](result, int(tokens[index + 1]))
        index += 2

    return result
"}

